import React, { forwardRef, ReactNode } from 'react';
import { useIntl } from 'react-intl';
import styled from 'styled-components';

import Spacings from '@dynatrace/strato-design-tokens/spacings';
import { XmarkIcon } from '@dynatrace/strato-icons';

import { BaseModalProps, BaseModal } from './BaseModal.js';
import type { ModalSizeOptionsType } from './types.js';
import { Button } from '../../buttons/button/Button.js';
import { HeadingLevel } from '../../core/types/heading.js';
import type { WithChildren } from '../../core/types/with-children.js';
import { Divider } from '../../typography/Divider.js';
import { Heading } from '../../typography/Heading.js';

export interface ModalProps extends WithChildren, BaseModalProps {
  /** Title of the modal, which is shown in the header section. */
  title: string;
  /** Footer section of the modal, where customized content can be added. */
  footer?: ReactNode;
}

/** Determines the visual heading level for a modal size */
function getVisualHeadingLevelForSize(
  size: ModalSizeOptionsType,
): HeadingLevel {
  switch (size) {
    case 'small':
      return 5;
    case 'medium':
    case 'large':
      return 4;
    default:
      return 4;
  }
}

// #region StyledComponents
const StyledHeader = /* @__PURE__ */ styled('header')({
  display: 'flex',
  justifyContent: 'space-between',
  alignItems: 'center',
  gap: Spacings.Size8,
  padding: `${Spacings.Size16} ${Spacings.Size24} ${Spacings.Size8}`,
});

const StyledDividerContainer = /* @__PURE__ */ styled.div({
  paddingTop: Spacings.Size0,
  paddingRight: Spacings.Size24,
  paddingBottom: Spacings.Size0,
  paddingLeft: Spacings.Size24,
});

const StyledDismissButton = /* @__PURE__ */ styled(Button)({
  alignSelf: 'start',
});

const StyledContent = /* @__PURE__ */ styled('div')<{ $footer: boolean }>(
  ({ $footer }) => {
    return {
      overflowY: 'auto',
      paddingTop: Spacings.Size12,
      paddingRight: Spacings.Size24,
      paddingBottom: $footer ? Spacings.Size12 : Spacings.Size24,
      paddingLeft: Spacings.Size24,
    };
  },
);

const StyledHeading = /* @__PURE__ */ styled(Heading)({
  wordBreak: 'normal',
  overflowWrap: 'anywhere',
});

const StyledFooter = /* @__PURE__ */ styled('footer')({
  display: 'flex',
  alignItems: 'flex-end',
  justifyContent: 'flex-end',
  padding: Spacings.Size24,
  paddingTop: Spacings.Size12,
});
// #endregion

/**
 * The `Modal` component lets you show important, additional content in an overlay.
 */
export const Modal = /* @__PURE__ */ forwardRef<HTMLDivElement, ModalProps>(
  (props, forwardedRef) => {
    const {
      show = false,
      title,
      footer,
      size = 'medium',
      children,
      onDismiss,
      dismissible = true,
    } = props;

    const visualHeadingSize = getVisualHeadingLevelForSize(size);

    const intl = useIntl();

    const closeButtonLabel = intl.formatMessage({
      defaultMessage: 'Close modal',
      id: 'aB3uCeB71q6UURBy',
      description: 'Aria-label for close modal button.',
    });

    return (
      <BaseModal
        aria-labelledby="strato-components-modal-title"
        show={show}
        size={size}
        onDismiss={onDismiss}
        dismissible={dismissible}
        ref={forwardedRef}
        data-testid="modal"
      >
        <StyledHeader>
          <StyledHeading
            id="strato-components-modal-title"
            level={visualHeadingSize}
            forwardedAs="h2"
          >
            {title}
          </StyledHeading>
          {dismissible && (
            <StyledDismissButton
              onClick={onDismiss}
              data-testid="modal-close-btn"
              aria-label={closeButtonLabel}
              variant="default"
            >
              <Button.Prefix>
                <XmarkIcon />
              </Button.Prefix>
            </StyledDismissButton>
          )}
        </StyledHeader>
        {(children || footer) && (
          <StyledDividerContainer>
            <Divider />
          </StyledDividerContainer>
        )}
        {children && (
          <StyledContent $footer={!!footer}>{children}</StyledContent>
        )}
        {footer && <StyledFooter>{footer}</StyledFooter>}
      </BaseModal>
    );
  },
);
(Modal as typeof Modal & { displayName: string }).displayName = 'Modal';
